const key='bordeon-workspace-demo-v1';
const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n/100);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const uid=prefix=>`${prefix}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
const seed=()=>({records:[{id:'BRD-2026-0142',customer:'Nordic Marine Ltd',risk:'MV Example Vessel',date:'2026-10-01',value:2450000000,premium:12000000,commission:15,status:'Policy active',versions:[{number:1,date:'2026-10-01',value:2450000000,note:'Original policy bound'}],transactions:[{id:'TX-001',date:'2026-10-01',type:'Initial premium',gross:12000000,commission:15,version:1}],carriers:[{name:'Northstar Insurance (demo)',share:60},{name:'Baltic Specialty (demo)',share:40}],binder:'MARINE-2026',reports:[]}]});
let state,storageAvailable=true;try{state=JSON.parse(localStorage.getItem(key));if(!state||!Array.isArray(state.records)||!state.records.length)state=seed();}catch{state=seed();storageAvailable=false;}
let active=state.records[0].id,view='bound',onSave;
const titles={bound:'Bound Business',policy:'Policy',endorsement:'Endorsement',carrier:'Carrier / Binder',bordereaux:'Bordereaux',settlement:'Settlement'};
const record=()=>state.records.find(r=>r.id===active);
const net=t=>t.gross-Math.round(t.gross*t.commission/100);
const rows=(heads,body)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
const badge=s=>`<span class="badge ${s==='Policy active'||s==='Settled (demo)'?'green':''}">${esc(s)}</span>`;
function panel(title,sub,body,action=''){return `<div class="panel"><div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>${body}</div>`;}
function button(label,action,cls='primary'){return `<button class="${cls}" data-action="${action}">${label}</button>`;}
function empty(title,copy){return `<div class="empty"><h3>${title}</h3><p>${copy}</p></div>`;}
function persist(message){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageAvailable=false;}render();document.querySelector('#notice').textContent=message+(storageAvailable?'':' Changes are available this session only; browser storage is unavailable.');}
function render(){
 const r=record(),allTx=state.records.flatMap(r=>r.transactions),obligations=state.records.flatMap(r=>r.reports.flatMap(report=>report.allocations));
 document.querySelector('#page-title').textContent=titles[view];
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 document.querySelector('#active-policy').innerHTML=state.records.map(x=>`<option value="${esc(x.id)}" ${x.id===active?'selected':''}>${esc(x.id)} · ${esc(x.customer)}</option>`).join('');
 document.querySelector('#record-state').innerHTML=badge(r.status);
 const metrics=[['Active policies',state.records.filter(x=>x.versions.length).length,'Across this demo workspace'],['Gross premium',money(allTx.reduce((a,t)=>a+t.gross,0)),'Including all adjustments'],['Open obligations',money(obligations.filter(a=>!a.settled).reduce((s,a)=>s+a.net,0)),'Generated from bordereaux'],['Bordereaux',state.records.reduce((s,r)=>s+r.reports.length,0),'Saved report snapshots']];
 document.querySelector('#metrics').innerHTML=metrics.map(([label,value,note])=>`<div class="metric"><small>${label}</small><strong>${value}</strong><span>${note}</span></div>`).join('');
 let body='';
 if(view==='bound')body=panel('Accepted business','Register a bound risk, then create its first policy version.',rows(['Reference / Customer','Risk','Accepted','Premium','Status',''],state.records.map(x=>`<tr><td><b>${esc(x.id)}</b><small>${esc(x.customer)}</small></td><td>${esc(x.risk)}</td><td>${esc(x.date)}</td><td>${money(x.premium)}</td><td>${badge(x.status)}</td><td><button class="quiet" data-open="${esc(x.id)}">Open →</button></td></tr>`).join('')),button('+ Add business','add'));
 else if(!r.versions.length&&view!=='policy')body=panel('Create a policy first','This record is accepted business.',empty('Ready for the next step','Open Policy to create the versioned record and initial premium transaction.'),button('Go to policy','policy'));
 else if(view==='policy'){
  const v=r.versions.at(-1);
  body=`<div class="grid">${panel('Policy record',esc(r.id),`<dl class="detail-grid"><div><dt>Customer</dt><dd>${esc(r.customer)}</dd></div><div><dt>Insured risk</dt><dd>${esc(r.risk)}</dd></div><div><dt>Insured value</dt><dd>${money(v?v.value:r.value)}</dd></div><div><dt>Currency</dt><dd>EUR</dd></div><div><dt>Current version</dt><dd>${v?'v'+v.number:'Not yet created'}</dd></div><div><dt>Commission</dt><dd>${r.commission}%</dd></div></dl>`,v?button('Add endorsement','endorsement'):button('Create policy','bind'))}${panel('Version history','Each change preserves the previous version.',v?`<ol class="history">${[...r.versions].reverse().map(v=>`<li><b>v${v.number} · ${esc(v.note)}</b><small>Effective ${esc(v.date)} · Insured value ${money(v.value)}</small></li>`).join('')}</ol>`:empty('No policy versions yet','Create the policy to start its history.'))}</div>`;
 }
 else if(view==='endorsement')body=panel('Endorsements & premium transactions','Enter an agreed adjustment. This demo does not calculate an insurance quote.',rows(['Transaction','Effective date','Type / Version','Gross premium','Commission','Net premium'],r.transactions.map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(t.date)}</td><td>${esc(t.type)}<small>Policy v${t.version}</small></td><td>${money(t.gross)}</td><td>${money(t.gross-net(t))}</td><td>${money(net(t))}</td></tr>`).join('')),button('+ Add endorsement','amend'));
 else if(view==='carrier')body=panel('Carrier participation','Shares apply to future reports. Saved bordereaux retain their original allocation.',rows(['Carrier','Binder / Facility','Written share'],r.carriers.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(r.binder)}</td><td>${c.share}%</td></tr>`).join(''))+'<div class="callout">Carrier shares must total 100%. Net premium is allocated after commission. Rounding is balanced to the total.</div>',button('Edit allocation','allocate'));
 else if(view==='bordereaux'){
  const reported=new Set(r.reports.flatMap(b=>b.transactions.map(t=>t.id))),pending=r.transactions.filter(t=>!reported.has(t.id));
  body=panel('Carrier bordereaux','Each report snapshots unreported transactions and creates matching settlement obligations.',`<div class="callout">${pending.length} unreported transaction${pending.length===1?'':'s'} · ${money(pending.reduce((s,t)=>s+net(t),0))} net premium</div><br>`+(r.reports.length?rows(['Report','Created','Transactions','Net premium',''],[...r.reports].reverse().map(b=>`<tr><td><b>${esc(b.id)}</b><small>${esc(b.binder)}</small></td><td>${b.date}</td><td>${b.transactions.length}</td><td>${money(b.allocations.reduce((s,a)=>s+a.net,0))}</td><td><button class="quiet" data-download="${esc(b.id)}">Download CSV ↓</button></td></tr>`).join('')):empty('No reports generated','Generate your first bordereau from the policy premium.')),`<button class="primary" data-action="generate" ${pending.length?'':'disabled'}>Generate bordereau</button>`);
 }
 else if(view==='settlement'){
  const allocations=r.reports.flatMap(b=>b.allocations.map((a,i)=>({...a,report:b.id,index:i,date:b.date})));
  body=panel('Settlement obligations','Amounts due to counterparties, traced back to each bordereau. No payments are executed.',allocations.length?rows(['Carrier / Report','Created','Net amount due','Status',''],allocations.map(a=>`<tr><td>${esc(a.name)}<small>${esc(a.report)}</small></td><td>${a.date}</td><td>${money(a.net)}</td><td>${badge(a.settled?'Settled (demo)':'Open')}</td><td>${a.settled?'—':`<button class="quiet" data-settle="${esc(a.report)}" data-index="${a.index}">Mark settled (demo)</button>`}</td></tr>`).join('')):empty('No obligations yet','Generate a bordereau to create the associated carrier obligations.'),button('View bordereaux','bordereaux','secondary'));
 }
 document.querySelector('#view').innerHTML=body;
}
function field(label,name,value='',type='text',extra=''){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" required ${extra}>`;}
function modal(title,fields,handler,label='Save'){document.querySelector('#modal-title').textContent=title;document.querySelector('#fields').innerHTML=fields;document.querySelector('#form-error').textContent='';document.querySelector('#save').textContent=label;onSave=handler;document.querySelector('#modal').showModal();}
const cents=(d,k)=>Math.round(Number(d.get(k))*100);
function act(action){
 const r=record();
 if(titles[action]){view=action;render();return;}
 if(action==='add')modal('Add accepted business',field('Customer','customer')+field('Insured risk','risk')+field('Accepted date','date',today(),'date')+field('Insured value (EUR)','value','','number','min="0.01" max="1000000000" step="0.01"')+field('Gross premium (EUR)','premium','','number','min="0.01" max="100000000" step="0.01"')+field('Commission (%)','commission',15,'number','min="0" max="100" step="0.01"'),d=>{if(!d.get('customer').trim()||!d.get('risk').trim())throw Error('Enter a customer and insured risk.');const x={id:uid('BRD'),customer:d.get('customer').trim(),risk:d.get('risk').trim(),date:d.get('date'),value:cents(d,'value'),premium:cents(d,'premium'),commission:Number(d.get('commission')),status:'Accepted',versions:[],transactions:[],carriers:[{name:'Northstar Insurance (demo)',share:60},{name:'Baltic Specialty (demo)',share:40}],binder:'DEMO-BINDER',reports:[]};state.records.push(x);active=x.id;view='policy';persist('Accepted business saved. Create the policy to continue.');});
 if(action==='bind'&&!r.versions.length){r.versions.push({number:1,date:r.date,value:r.value,note:'Original policy bound'});r.transactions.push({id:uid('TX'),date:r.date,type:'Initial premium',gross:r.premium,commission:r.commission,version:1});r.status='Policy active';persist('Policy v1 and the initial premium transaction created.');}
 if(action==='amend')modal('Add endorsement',field('Change description','note')+field('Effective date','date',today(),'date',`min="${r.versions.at(-1).date}"`)+field('New insured value (EUR)','value',r.versions.at(-1).value/100,'number','min="0.01" max="1000000000" step="0.01"')+field('Premium adjustment (EUR)','delta',0,'number','min="-100000000" max="100000000" step="0.01"')+'<p>Use a positive amount for additional premium or a negative amount for return premium. Commission follows the policy rate.</p>',d=>{if(!d.get('note').trim())throw Error('Enter a description of the change.');const delta=cents(d,'delta');if(r.transactions.reduce((s,t)=>s+t.gross,0)+delta<0)throw Error('Return premium cannot exceed the total gross premium.');const number=r.versions.length+1;r.versions.push({number,date:d.get('date'),value:cents(d,'value'),note:d.get('note').trim()});r.transactions.push({id:uid('TX'),date:d.get('date'),type:delta<0?'Return premium':delta>0?'Additional premium':'No premium change',gross:delta,commission:r.commission,version:number});persist(`Policy v${number} and linked premium adjustment saved.`);});
 if(action==='allocate')modal('Carrier / binder allocation',field('Binder / facility','binder',r.binder)+field('Carrier 1','first',r.carriers[0].name)+field('Carrier 1 share (%)','share',r.carriers[0].share,'number','min="0" max="100" step="0.01"')+field('Carrier 2','second',r.carriers[1].name)+'<p>The remaining share is assigned to carrier 2. Changes affect new reports only.</p>',d=>{if(!d.get('first').trim()||!d.get('second').trim()||!d.get('binder').trim())throw Error('Enter both carrier names and a binder.');if(d.get('first').trim().toLowerCase()===d.get('second').trim().toLowerCase())throw Error('Use two different carriers.');const share=Number(d.get('share'));r.binder=d.get('binder').trim();r.carriers=[{name:d.get('first').trim(),share},{name:d.get('second').trim(),share:Math.round((100-share)*100)/100}];persist('Allocation updated for future bordereaux.');});
 if(action==='generate'){
  const reported=new Set(r.reports.flatMap(b=>b.transactions.map(t=>t.id))),tx=r.transactions.filter(t=>!reported.has(t.id));if(!tx.length)return;
  const total=tx.reduce((s,t)=>s+net(t),0),first=Math.round(total*r.carriers[0].share/100);
  r.reports.push({id:uid('BDX'),date:today(),binder:r.binder,transactions:structuredClone(tx),allocations:r.carriers.map((c,i)=>({...c,net:i===0?first:total-first,settled:false}))});persist('Bordereau saved. Matching carrier settlement obligations created.');
 }
}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();}));
document.querySelector('#active-policy').addEventListener('change',e=>{active=e.target.value;render();});
document.querySelector('#close-modal').addEventListener('click',()=>document.querySelector('#modal').close());
document.querySelector('#edit-form').addEventListener('submit',e=>{e.preventDefault();try{onSave(new FormData(e.currentTarget));document.querySelector('#modal').close();}catch(error){document.querySelector('#form-error').textContent=error.message;}});
document.querySelector('#reset').addEventListener('click',()=>modal('Reset this demo?','<p>This replaces all local test records and reports with the original sample. Download any bordereaux you want to keep first.</p>',()=>{state=seed();active=state.records[0].id;view='bound';persist('Demo reset to the original sample.');},'Reset demo'));
document.querySelector('#view').addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.action)act(b.dataset.action);
 if(b.dataset.open){active=b.dataset.open;view='policy';render();}
 if(b.dataset.settle){const report=record().reports.find(r=>r.id===b.dataset.settle),allocation=report.allocations[Number(b.dataset.index)];modal('Record a demo settlement',`<p>Mark ${esc(allocation.name)}’s obligation of ${money(allocation.net)} as settled in this browser. This does not send money or update an external system.</p>`,()=>{allocation.settled=true;persist('Demo settlement recorded. No payment was executed.');},'Mark settled (demo)');}
 if(b.dataset.download){const r=record(),report=r.reports.find(x=>x.id===b.dataset.download);const csvCell=value=>{let s=String(value);if(/^[=+@\-\t\r]/.test(s)&&typeof value!=='number')s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const data=[['report','policy','customer','binder','transaction','effective_date','version','type','gross_eur','commission_eur','net_eur'],...report.transactions.map(t=>[report.id,r.id,r.customer,report.binder,t.id,t.date,t.version,t.type,t.gross/100,(t.gross-net(t))/100,net(t)/100]),[],['carrier','share_percent','net_due_eur'],...report.allocations.map(a=>[a.name,a.share,a.net/100])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=report.id+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
render();if(!storageAvailable)document.querySelector('#notice').textContent='Browser storage is unavailable. Changes will last for this session only.';
